# Shard locator: consistent hashing maps keys to shards; replicas listed.
import hashlib
shards = ['s0','s1','s2']
def h(key):
    return int(hashlib.md5(key.encode()).hexdigest(), 16)
def locate(key, n_replicas=1):
    order = sorted(shards, key=lambda s: h(s + "#" + "x"))
    primary = order[h(key) % len(order)]
    idx = order.index(primary)
    return [order[(idx + i) % len(order)] for i in range(n_replicas)]
for key in ['user:1','user:2','order:9']:
    print(f"{key} -> {locate(key)}")

